list_currencies.code:
const response = await client.currencies.listCurrencies({search: 'dollar', active: true});
for (const currency of response.map.currencies) {
    console.log(currency.id, currency.code, currency.name, currency.conversion_rate, currency.base);
}
console.log(response.map.pagination.total, response.map.pagination.has_next);

create_currency.code:
const response = await client.currencies.createCurrency({
    name: 'Example Dollar',
    code: 'XEX',
    symbol: '$',
    country: 'NZ',
    conversion_rate: 1.2345,
    precision: 2,
    rounding: 'nearest',
    active: true,
}, {transactionNo: 'TXN-IMPORT-0001'});
console.log(response.map.currency.id, response.map.currency.code, response.map.currency.base);

get_currency.code:
const response = await client.currencies.getCurrency(1234, {field_metadata: true});
const currency = response.map.currency;
console.log(currency.name, currency.code, currency.symbol, currency.conversion_rate, currency.country.code);
console.log(response.map.field_metadata.code.pattern, response.headers.etag);

update_currency.code:
const response = await client.currencies.updateCurrency(1234, {
    name: 'Example Dollar',
    code: 'XEX',
    symbol: '$',
    country: {code: 'US'},
    conversion_rate: 1.5,
    precision: 3,
    rounding: 'up',
    active: false,
});
const currency = response.map.currency;
console.log(currency.country.code, currency.conversion_rate, currency.rounding, currency.active);

set_base_currency.code:
const response = await client.currencies.setBaseCurrency(1234);
console.log(response.map.currency.code, response.map.currency.base);
console.log(response.map.previous_base?.code);
